#import "KARPAHistory.h"
static NSString *HP(NSString *d){return [d stringByAppendingPathComponent:@"collection_history.json"];} 
NSArray<NSDictionary *> *KARPAReadHistory(NSString *d,NSError **e){NSData *x=[NSData dataWithContentsOfFile:HP(d)];if(!x)return @[];id o=[NSJSONSerialization JSONObjectWithData:x options:0 error:e];return [o isKindOfClass:NSArray.class]?o:@[];}
BOOL KARPAAppendHistory(NSDictionary *r,NSString *d,NSError **e){if(![d isKindOfClass:NSString.class]||![r isKindOfClass:NSDictionary.class]){if(e)*e=[NSError errorWithDomain:@"com.example.authorized.KARPA" code:40 userInfo:@{NSLocalizedDescriptionKey:@"Invalid history input"}];return NO;}NSMutableArray *a=[[KARPAReadHistory(d,NULL) mutableCopy]?:[NSMutableArray array]];NSDictionary *entry=@{ @"timestamp":[[NSDate date] description],@"classCount":r[@"runtime"][@"classCountObserved"]?:@0,@"methodCount":r[@"runtime"][@"methodsObserved"]?:@0,@"status":r[@"diagnostics"][@"status"]?:@"UNKNOWN",@"directory":d};[a addObject:entry];NSData *x=[NSJSONSerialization dataWithJSONObject:a options:NSJSONWritingPrettyPrinted error:e];return x&&[x writeToFile:HP(d) options:NSDataWritingAtomic error:e];}
